#include <stdio.h>

int max_int(int a, int b) {
    return a > b ? a : b;
}

int main(void) {
    printf("%d\n", max_int(4, 9));
    return 0;
}

#include <stdio.h>

int factorial(int n) {
    int result = 1;
    for (int value = 2; value <= n; value++) {
        result *= value;
    }
    return result;
}

#include <stdio.h>

int sum_array(const int values[], size_t count) {
    int total = 0;
    for (size_t index = 0; index < count; index++) {
        total += values[index];
    }
    return total;
}

#include <stdio.h>

void reverse_array(int values[], size_t count) {
    for (size_t left = 0; left < count / 2; left++) {
        size_t right = count - left - 1;
        int temporary = values[left];
        values[left] = values[right];
        values[right] = temporary;
    }
}

#include <stddef.h>

int find_value(const int values[], size_t count, int target) {
    for (size_t index = 0; index < count; index++) {
        if (values[index] == target) {
            return (int)index;
        }
    }
    return -1;
}

#include <stdio.h>

int is_even(int value) {
    return value % 2 == 0;
}

int main(void) {
    for (int value = 0; value < 10; value++) {
        if (is_even(value)) {
            printf("%d ", value);
        }
    }
    return 0;
}

#include <stdlib.h>

int compare_ints(const void *left, const void *right) {
    const int first = *(const int *)left;
    const int second = *(const int *)right;
    return (first > second) - (first < second);
}

#include <stdio.h>

void print_matrix(int rows, int columns, int matrix[rows][columns]) {
    for (int row = 0; row < rows; row++) {
        for (int column = 0; column < columns; column++) {
            printf("%d ", matrix[row][column]);
        }
        putchar('\n');
    }
}

#include <stddef.h>

size_t string_length(const char *text) {
    size_t length = 0;
    while (text[length] != '\0') {
        length++;
    }
    return length;
}

#include <stddef.h>

void copy_string(char *destination, size_t capacity, const char *source) {
    size_t index = 0;
    if (capacity == 0) {
        return;
    }
    while (source[index] != '\0' && index + 1 < capacity) {
        destination[index] = source[index];
        index++;
    }
    destination[index] = '\0';
}

#include <stdio.h>

int count_characters(const char *text, char target) {
    int count = 0;
    for (size_t index = 0; text[index] != '\0'; index++) {
        if (text[index] == target) {
            count++;
        }
    }
    return count;
}

#include <stdlib.h>

int *make_range(int count) {
    int *values = malloc((size_t)count * sizeof(*values));
    if (values == NULL) {
        return NULL;
    }
    for (int index = 0; index < count; index++) {
        values[index] = index;
    }
    return values;
}

#include <stdlib.h>

void destroy_buffer(int **buffer) {
    if (buffer != NULL && *buffer != NULL) {
        free(*buffer);
        *buffer = NULL;
    }
}

#include <stdbool.h>

bool starts_with(const char *text, const char *prefix) {
    while (*prefix != '\0') {
        if (*text++ != *prefix++) {
            return false;
        }
    }
    return true;
}

