#include <stdio.h>

int read_positive(void) {
    int value = 0;
    do {
        if (scanf("%d", &value) != 1) {
            return -1;
        }
    } while (value <= 0);
    return value;
}

#include <assert.h>

static int square(int value) {
    return value * value;
}

int main(void) {
    assert(square(5) == 25);
    return 0;
}

#include <stdio.h>

struct Point {
    int x;
    int y;
};

int manhattan_distance(struct Point point) {
    int x = point.x < 0 ? -point.x : point.x;
    int y = point.y < 0 ? -point.y : point.y;
    return x + y;
}

#include <stddef.h>

struct Node {
    int value;
    struct Node *next;
};

size_t list_length(const struct Node *head) {
    size_t length = 0;
    for (const struct Node *node = head; node != NULL; node = node->next) {
        length++;
    }
    return length;
}
